import attr
import pickle

@attr.s(slots=True)
class C:
    x = attr.ib()
    y = attr.ib()

def test_backward_compatibility():
    c = C(1, 2)
    print(f"Before: x={c.x}, y={c.y}")

    # Simulate old pickle state (tuple)
    state = (10, 20)
    try:
        c.__setstate__(state)
        print(f"After: x={c.x}, y={c.y}")
    except Exception as e:
        print(f"Error: {e}")

    assert c.x == 10
    assert c.y == 20

if __name__ == "__main__":
    try:
        test_backward_compatibility()
        print("Test passed!")
    except AssertionError:
        print("Test failed: values were not updated")
    except Exception as e:
        print(f"Test failed with error: {e}")

import attr
import pickle

@attr.s(slots=True)
class C:
    x = attr.ib()
    y = attr.ib()

def slots_setstate_fixed(self, state, state_attr_names, _obj_setattr, hash_caching_enabled, _hash_cache_field):
    __bound_setattr = _obj_setattr.__get__(self)
    if isinstance(state, tuple):
        for name, value in zip(state_attr_names, state):
            __bound_setattr(name, value)
    else:
        for name in state_attr_names:
            if name in state:
                __bound_setattr(name, state[name])

    if hash_caching_enabled:
        __bound_setattr(_hash_cache_field, None)

def test_backward_compatibility():
    c = C(1, 2)
    print(f"Before: x={c.x}, y={c.y}")

    state = (10, 20)
    state_attr_names = ('x', 'y')
    _obj_setattr = object.__setattr__
    hash_caching_enabled = False
    _hash_cache_field = "_attrs_cached_hash"

    slots_setstate_fixed(c, state, state_attr_names, _obj_setattr, hash_caching_enabled, _hash_cache_field)
    print(f"After: x={c.x}, y={c.y}")

    assert c.x == 10
    assert c.y == 20

def test_current_compatibility():
    c = C(1, 2)
    print(f"Before: x={c.x}, y={c.y}")

    state = {'x': 10, 'y': 20}
    state_attr_names = ('x', 'y')
    _obj_setattr = object.__setattr__
    hash_caching_enabled = False
    _hash_cache_field = "_attrs_cached_hash"

    slots_setstate_fixed(c, state, state_attr_names, _obj_setattr, hash_caching_enabled, _hash_cache_field)
    print(f"After: x={c.x}, y={c.y}")

    assert c.x == 10
    assert c.y == 20

if __name__ == "__main__":
    try:
        test_backward_compatibility()
        print("Backward compatibility test passed!")
        test_current_compatibility()
        print("Current compatibility test passed!")
    except AssertionError:
        print("Test failed")
    except Exception as e:
        print(f"Test failed with error: {e}")

